def max_refund(captured_cents, refunded_cents):
    return max(0, captured_cents - refunded_cents)

def can_refund(captured_cents, refunded_cents, request_cents):
    return request_cents > 0 and request_cents <= max_refund(captured_cents, refunded_cents)
